import{z as o,x as s,o as A,c as C,q as n,j as r,D as a,d as t,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"清算与结算","description":"","frontmatter":{"title":"清算与结算","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-clearing-settlement.md","filePath":"quant/gm-clearing-settlement.md","lastUpdated":1791413859000}'),D={name:"quant/gm-clearing-settlement.md"};function d(m,E,p,u,f,F){const B=s("Mermaid");return A(),C("div",null,[E[2]||(E[2]=n('<h1 id="清算与结算" tabindex="-1">清算与结算 <a class="header-anchor" href="#清算与结算" aria-label="Permalink to &quot;清算与结算&quot;">​</a></h1><div class="epigraph"><p>执行课程到成交为止，制度课还差一半：中央对手把散乱的对手关系收成一个节点，结算周期决定你暴露在这个节点外多久——后链的结构是前台的隐形参数。</p><footer>—— 据 Duffie and Zhu, Review of Asset Pricing Studies, 2011；Pirrong, The Economics of Central Clearing, 2011；BIS/CPMI 报告口径整理</footer></div><p><a href="/quant/gm-crypto-regime">上一课</a>用加密市场把「成交不等于拿到资产」推到极致。法币市场把成交之后的链条整体制度化：清算（确认、净额、对手替换）与结算（券款对付、最终性）。前面六课各写了一个市场的场所层，本课起转入机制单元：把这条后链拆开，写它如何进入策略的资金账与风险账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一缺口是中央对手（CCP）改变风险形状：对手替换（novation）把对每个经纪商的散乱敞口收成对 CCP 的单一敞口，多边净额压缩名义义务——净额收益取决于参与者结构与违约相关性（Duffie and Zhu 2011 的问题设定），而 CCP 自己成为系统重要性节点，违约瀑布（违约方保证金、违约基金、自留份额、逐级分摊）把尾部风险重新分配给成员。第二缺口是周期：现货从 T+2 向 T+1 迁移已成趋势——美股 2024 年起 T+1，欧盟、日本等相继排期，印度已全面 T+1；周期决定资金与券的占用窗口、失败交割的处置窗口、以及跨市场配对簿基差敞口的长度。第三缺口是外汇腿：跨币种结算存在时区错切的赫斯塔特风险，持续联结结算（CLS）以支付对支付消除它——不做跨币种的策略感受不到这条约束，做了马上遇到。</p><p><span class="marginnote">「中央对手」翻译成大白话：清算所站到每笔交易的中间，对买方它当卖方、对卖方它当买方。你不再需要担心「对面那家经纪商会不会倒」，改为统一担心「清算所的缓冲够不够」——把 N 个对手风险打包成一个，这就是对手替换的含义。</span></p><p><span class="marginnote">配对簿的基差敞口长度由两边结算周期差决定：一边 T+1 一边 T+2 时，券已到手的一侧与钱未付出的另一侧错开一天——对冲比率再准，也压不住结算日历多暴露的这一天。</span></p><p><span class="marginnote">数字实例：T+1 意思是成交日后下一个工作日钱券交割。假设周一成交买入美股，T+2 制度下周三上午你的券才可动用，期间卖出现金腿的资金周三才到账；迁到 T+1 后敞口窗口从约 48 小时压到约 24 小时，但隔夜对账、失败纠正只剩几个小时——红利与压力来自同一个压缩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机制清单四项。对手结构：逐经纪商归档其清算路径（自营清算还是代清算）、CCP 归属与违约瀑布分摊条款——对手限额按清算结构而非名义持仓设。保证金：初始与变动保证金的口径、追缴时点与压力期上调历史入表，资金计划按「追缴早于你的收款」的错位情景做。周期与日历：每个市场记 T+n、结算货币、CSD（DTC、Euroclear 与 Clearstream、CCASS、JASDEC、印度的两家并存）与交收截止时点，配对策略按「两边都已最终结算」的日历计敞口。失败处理：各市场的失败罚金、强制买入或拍卖纪律入成本模型——<a href="/quant/gm-india">印度市场</a>的拍卖是其中最硬的一档，欧盟 CSDR 的罚金与买入安排是另一档。</p>',10)),(A(),r(l,null,{default:a(()=>[i(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E6%88%90%E4%BA%A4%22%5D%20--%3E%20CLR%5B%22%E6%B8%85%E7%AE%97%EF%BC%9A%E7%A1%AE%E8%AE%A4%E4%B8%8E%E5%87%80%E9%A2%9D%22%5D%0A%20%20CLR%20--%3E%20NOV%5B%22%E5%AF%B9%E6%89%8B%E6%9B%BF%E6%8D%A2%EF%BC%9ACCP%20%E5%90%8D%E4%B8%8B%22%5D%0A%20%20NOV%20--%3E%20MG%5B%22%E5%88%9D%E5%A7%8B%E4%BF%9D%E8%AF%81%E9%87%91%20%2B%20%E5%8F%98%E5%8A%A8%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20MG%20--%3E%20SET%5B%22%E7%BB%93%E7%AE%97%EF%BC%9A%E5%88%B8%E6%AC%BE%E5%AF%B9%E4%BB%98%E4%B8%8E%E6%9C%80%E7%BB%88%E6%80%A7%22%5D%0A%20%20SET%20--%3E%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%EF%BC%9A%E7%BD%9A%E9%87%91%20%2F%20%E4%B9%B0%E5%85%A5%20%2F%20%E6%8B%8D%E5%8D%96%22%5D%0A%20%20FX%5B%22%E8%B7%A8%E5%B8%81%E7%A7%8D%E8%85%BF%22%5D%20--%3E%20CLS%5B%22CLS%EF%BC%9A%E6%94%AF%E4%BB%98%E5%AF%B9%E6%94%AF%E4%BB%98%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"净额的机制是把双边敞口折叠：同名下轧差后，名义交易量巨大而实际义务很小；代价是风险集中——CCP 同时承担清算成员的违约与流动性压力，保证金是其主要缓冲，压力期上调保证金本身会放大市场资金紧张（2020 年 3 月的教训）。周期缩短的机制是把信用敞口窗口从三天压到一天：资本效率上升、失败风险窗口变短，但对账与公司行动的处理窗口同步压缩——周期红利只落到后链跟得上的机构手里。DvP 与最终性定义「什么时候真正换了手」：最终性之前，一切持仓都是过程态，风险与融资模型要用过程态口径记。CLS 的机制是把跨币种两腿同时交付：错切敞口从按天变成按秒。不这么做会错在哪：只用场所层的价差与费用建账，后链的保证金错位、周期差敞口与失败惩罚会以「偶发亏损」的形式回流——偶发但可预测，且集中在压力日。",-1)),E[5]||(E[5]=e("p",null,"一家清算成员违约时，损失按什么顺序被谁吸收，这条违约瀑布回答的是「我作为无辜成员会不会被摊到」：",-1)),(A(),r(l,null,{default:a(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E6%B8%85%E7%AE%97%E6%88%90%E5%91%98%E8%BF%9D%E7%BA%A6%22%5D%20--%3E%20L1%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%20%E8%BF%9D%E7%BA%A6%E6%96%B9%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20L1%20--%3E%20G%7B%22%E6%8D%9F%E5%A4%B1%E8%A1%A5%E5%AE%8C%E4%BA%86%E5%90%97%22%7D%0A%20%20G%20--%20%22%E5%90%A6%22%20--%3E%20L2%5B%22%E7%AC%AC%E4%BA%8C%E5%B1%82%20%E8%BF%9D%E7%BA%A6%E5%9F%BA%E9%87%91%20%E6%B1%A0%22%5D%0A%20%20L2%20--%3E%20G2%7B%22%E8%A1%A5%E5%AE%8C%E4%BA%86%E5%90%97%22%7D%0A%20%20G2%20--%20%22%E5%90%A6%22%20--%3E%20L3%5B%22%E7%AC%AC%E4%B8%89%E5%B1%82%20CCP%20%E8%87%AA%E7%95%99%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20L3%20--%3E%20G3%7B%22%E8%A1%A5%E5%AE%8C%E4%BA%86%E5%90%97%22%7D%0A%20%20G3%20--%20%22%E5%90%A6%22%20--%3E%20L4%5B%22%E7%AC%AC%E5%9B%9B%E5%B1%82%20%E5%B9%B8%E5%AD%98%E6%88%90%E5%91%98%E6%8C%89%E4%BB%BD%E9%A2%9D%E5%88%86%E6%91%8A%22%5D%0A%20%20G%20--%20%22%E6%98%AF%22%20--%3E%20Done%5B%22%E5%A4%84%E7%BD%AE%E7%BB%93%E6%9D%9F%22%5D%0A%20%20G2%20--%20%22%E6%98%AF%22%20--%3E%20Done%0A%20%20G3%20--%20%22%E6%98%AF%22%20--%3E%20Done%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">直觉类比：违约瀑布像大楼的消防系统分级——先烧违约者自己房间里的灭火器（其保证金），再动用全楼共用的消防水箱（违约基金），然后是物业自备的储备（自留份额），最后才向每家住户收分摊费。你交违约基金，买的就是「不必用到第四层」的优先级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写现货链；衍生品组合的净额与 XVA 定价在利率信用课程已写，不重复。证券借贷的定价与召回动态、CSDR 买入条款的执行细则不展开。各市场的周期与截止时点以当期规则为准——这正是本课的论点：后链参数是会变的制度常量，清单要带日期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CCP 用对手替换与多边净额重排对手风险，代价是风险集中与违约瀑布分摊。</li><li>结算周期决定占用与失败窗口：T+1 迁移是趋势，红利只到后链跟得上的机构。</li><li>配对簿的基差敞口按「两边都已最终结算」的日历计，周期差直接加敞口天数。</li><li>跨币种腿的错切风险由 CLS 类支付对支付机制消除，不做跨币种也要知道它在哪。</li><li>出处：Duffie and Zhu, <em>Review of Asset Pricing Studies</em>, 2011；Pirrong, <em>The Economics of Central Clearing</em>, 2011；BIS/CPMI 与各 CSD 公开口径。</li></ul>',5))])}const c=o(D,[["render",d]]);export{h as __pageData,c as default};
